const emptyRule = () => ({ listSelector: '', linkSelector: '', titleSelector: '', contentSelector: '', authorSelector: '', publishTimeSelector: '', urlPattern: '' });
const emptyForm = () => ({ id: null, sourceCode: '', sourceName: '', sourceType: 'WEB_LIST', entryUrl: '', collectionDescription: '', allowedDomain: '', scheduleCron: '0 */10 * * * *', enabled: false, configuration: { sleepMillis: 1000, timeoutMillis: 20000, zoneId: 'Asia/Shanghai', language: 'zh-CN', legalRisk: false, scheduleWindowEnabled: false, scheduleWindowStart: '09:00', scheduleWindowEnd: '12:00', attachmentSelector: '', attachmentAllowedDomains: '' }, rule: emptyRule() });
const intervalOptions = [
  { label: '5 分钟', cron: '0 */5 * * * *' },
  { label: '10 分钟', cron: '0 */10 * * * *' },
  { label: '15 分钟', cron: '0 */15 * * * *' },
  { label: '30 分钟', cron: '0 */30 * * * *' },
  { label: '1 小时', cron: '0 0 * * * *' },
  { label: '2 小时', cron: '0 0 */2 * * *' },
  { label: '4 小时', cron: '0 0 */4 * * *' },
  { label: '6 小时', cron: '0 0 */6 * * *' }
];
const weekdayOptions = [
  { label: '一', value: 'MON' }, { label: '二', value: 'TUE' }, { label: '三', value: 'WED' },
  { label: '四', value: 'THU' }, { label: '五', value: 'FRI' }, { label: '六', value: 'SAT' },
  { label: '日', value: 'SUN' }
];
const weekdayNumberMap = { '1': 'MON', '2': 'TUE', '3': 'WED', '4': 'THU', '5': 'FRI', '6': 'SAT', '0': 'SUN', '7': 'SUN' };
const monthDayOptions = [...Array.from({ length: 28 }, (_, index) => ({ label: String(index + 1), value: String(index + 1) })), { label: '末', value: 'L' }];
const emptyScheduleEditor = () => ({ mode: 'interval', intervalCron: '0 */10 * * * *', time: '09:00', weekdays: ['MON'], monthDays: ['1'] });
const sourceTypeOptions = [
  { label: '交易所首页', value: 'EXCHANGE_HOME' },
  { label: '深交所首页', value: 'SZSE_HOME' },
  { label: '香港交易所首页', value: 'HKEX_HOME' },
  { label: '中证指数首页指数图', value: 'CSINDEX_HOME' },
  { label: '中国债券信息网数据分析', value: 'CHINABOND_HOME' },
  { label: '交易所市场表现数据', value: 'EXCHANGE_MARKET_DATA' },
  { label: '交易所每日市场快照', value: 'EXCHANGE_DAILY_SNAPSHOT' },
  { label: '深交所披露栏目', value: 'SZSE_DISCLOSURE' },
  { label: '资讯首页', value: 'NEWS_HOME' },
  { label: '巨潮资讯首页', value: 'CNINFO_HOME' },
  { label: '财联社电报', value: 'CLS_TELEGRAPH' },
  { label: '东方财富 7×24 快讯', value: 'EASTMONEY_724' },
  { label: '结构化快讯模板', value: 'STRUCTURED_FLASH' },
  { label: '证券时报信息披露（内置）', value: 'STCN_DISCLOSURES' },
  { label: '巨潮公告', value: 'CNINFO_ANNOUNCEMENTS' },
  { label: '上交所公告', value: 'SSE_ANNOUNCEMENTS' },
  { label: '网页列表', value: 'WEB_LIST' },
  { label: '固定网页', value: 'WEB_SINGLE_PAGE' },
  { label: 'RSS/Atom', value: 'RSS' },
  { label: 'JSON API', value: 'API' }
];
const selectorPresets = {
  title: [
    { label: '文章标题（h1）', value: 'h1' },
    { label: '常用标题类（.title）', value: '.title' },
    { label: '文章标题类（.article-title）', value: '.article-title' },
    { label: '新闻标题类（.news-title）', value: '.news-title' },
    { label: '详情标题类（.detail-title）', value: '.detail-title' },
    { label: '结构化标题（[itemprop="headline"]）', value: '[itemprop="headline"]' }
  ],
  publishTime: [
    { label: 'HTML time 标签', value: 'time' },
    { label: '常用时间类（.time）', value: '.time' },
    { label: '发布时间类（.publish-time）', value: '.publish-time' },
    { label: '发布日期类（.publish-date）', value: '.publish-date' },
    { label: '文章时间类（.article-time）', value: '.article-time' },
    { label: '详情时间类（.detail-time）', value: '.detail-time' },
    { label: '结构化发布时间（[itemprop="datePublished"]）', value: '[itemprop="datePublished"]' }
  ],
  author: [
    { label: 'HTML address 标签', value: 'address' },
    { label: '常用作者类（.author）', value: '.author' },
    { label: '来源类（.source）', value: '.source' },
    { label: '文章来源类（.article-source）', value: '.article-source' },
    { label: '发布者类（.publisher）', value: '.publisher' },
    { label: '结构化作者（[itemprop="author"]）', value: '[itemprop="author"]' }
  ],
  content: [
    { label: 'HTML article 标签', value: 'article' },
    { label: '常用正文类（.content）', value: '.content' },
    { label: '文章正文类（.article-content）', value: '.article-content' },
    { label: '新闻正文类（.news-content）', value: '.news-content' },
    { label: '详情正文类（.detail-content）', value: '.detail-content' },
    { label: '正文容器（#content）', value: '#content' },
    { label: '文章容器（#article-content）', value: '#article-content' }
  ],
  attachment: [
    { label: '自动识别常见附件（推荐）', value: 'a[href$=".pdf"], a[href$=".doc"], a[href$=".docx"], a[href$=".xls"], a[href$=".xlsx"], a[href$=".csv"]' },
    { label: 'PDF 文件', value: 'a[href$=".pdf"]' },
    { label: 'Word 文件', value: 'a[href$=".doc"], a[href$=".docx"]' },
    { label: 'Excel/CSV 文件', value: 'a[href$=".xls"], a[href$=".xlsx"], a[href$=".csv"]' },
    { label: '附件区域链接（.attachment）', value: '.attachment a' },
    { label: '附件列表链接（.attachment-list）', value: '.attachment-list a' },
    { label: '下载区域链接（.download）', value: '.download a' }
  ]
};

function cronTime(hour, minute) {
  return `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;
}

function decodeCron(value) {
  const cron = String(value || '').trim();
  const interval = intervalOptions.find((option) => option.cron === cron);
  if (interval) return { ...emptyScheduleEditor(), mode: 'interval', intervalCron: interval.cron, description: `每隔 ${interval.label}` };
  const parts = cron.split(/\s+/);
  if (parts.length !== 6 || parts[0] !== '0' || !/^\d+$/.test(parts[1]) || !/^\d+$/.test(parts[2])) {
    return { ...emptyScheduleEditor(), mode: 'advanced', description: cron ? `自定义计划` : '未配置调度' };
  }
  const time = cronTime(parts[2], parts[1]);
  if (parts[3] === '*' && parts[4] === '*' && parts[5] === '*') {
    return { ...emptyScheduleEditor(), mode: 'daily', time, description: `每天 ${time}` };
  }
  if (parts[3] === '*' && parts[4] === '*' && parts[5] !== '*') {
    const weekdays = parts[5].split(',').map((day) => weekdayNumberMap[day] || day.toUpperCase()).filter((day) => weekdayOptions.some((option) => option.value === day));
    const labels = weekdays.map((day) => weekdayOptions.find((option) => option.value === day)?.label).filter(Boolean);
    return { ...emptyScheduleEditor(), mode: 'weekly', time, weekdays: weekdays.length ? weekdays : ['MON'], description: `每周${labels.join('、')} ${time}` };
  }
  if (parts[3] !== '*' && parts[4] === '*' && parts[5] === '*') {
    const monthDays = parts[3].split(',').filter((day) => monthDayOptions.some((option) => option.value === day));
    const labels = monthDays.map((day) => day === 'L' ? '最后一天' : `${day} 日`);
    return { ...emptyScheduleEditor(), mode: 'monthly', time, monthDays: monthDays.length ? monthDays : ['1'], description: `每月 ${labels.join('、')} ${time}` };
  }
  return { ...emptyScheduleEditor(), mode: 'advanced', description: '自定义计划' };
}

export default {
  name: 'NewsCollectionView',
  emits: ['notify', 'error', 'result'],
  data: () => ({
    sources: [], presets: [], patternPresets: [], collectionTemplates: [], selectedCollectionTemplateCode: '',
    structuredFlashConfigText: '',
    loading: false, saving: false, collectingId: null, checkingRobotsId: null, dialogOpen: false,
    robotsOverrideDialogOpen: false, robotsOverrideSaving: false, robotsOverrideSource: null,
    robotsOverrideForm: { reason: '', hours: 24, acknowledged: false },
    logDialogOpen: false, logsLoading: false, logs: [], logSourceId: '', logPage: 1, logPageSize: 20, logTotal: 0,
    filters: { keyword: '', sourceType: '', enabled: '' }, page: 1, pageSize: 10, pageSizes: [10, 20, 50, 100],
    form: emptyForm(), scheduleEditor: emptyScheduleEditor(), intervalOptions, weekdayOptions, monthDayOptions, sourceTypeOptions, selectorPresets
  }),
  computed: {
    filteredSources() {
      const keyword = String(this.filters.keyword || '').trim().toLowerCase();
      return this.sources.filter((source) => {
        const searchable = [source.sourceName, source.sourceCode, source.entryUrl, source.collectionDescription, source.allowedDomain, source.sourceType]
          .filter(Boolean)
          .join(' ')
          .toLowerCase();
        const keywordMatches = !keyword || searchable.includes(keyword);
        const typeMatches = !this.filters.sourceType || source.sourceType === this.filters.sourceType;
        const statusMatches = this.filters.enabled === '' || source.enabled === this.filters.enabled;
        return keywordMatches && typeMatches && statusMatches;
      }).sort((left, right) => Number(Boolean(right.configuration?.legalRisk)) - Number(Boolean(left.configuration?.legalRisk)));
    },
    pagedSources() {
      const start = (this.page - 1) * this.pageSize;
      return this.filteredSources.slice(start, start + this.pageSize);
    },
    selectedCollectionTemplate() {
      return this.collectionTemplates.find(template => template.code === this.selectedCollectionTemplateCode) || null;
    }
  },
  mounted() { this.load(); },
  methods: {
    async load() {
      this.loading = true;
      try {
        [this.sources, this.presets, this.patternPresets, this.collectionTemplates] = await Promise.all([
          newsApi.listSources(), newsApi.listPresets(), newsApi.listPatternPresets(), newsApi.listCollectionTemplates()
        ]);
      }
      catch (error) { this.$emit('error', error); }
      finally {
        const lastPage = Math.max(1, Math.ceil(this.filteredSources.length / this.pageSize));
        if (this.page > lastPage) this.page = lastPage;
        this.loading = false;
      }
    },
    async refreshSources() {
      await this.load();
      this.$emit('notify', { title: '资讯采集数据已刷新' });
    },
    async openLogs() {
      this.logDialogOpen = true;
      this.logPage = 1;
      await this.loadLogs();
    },
    async reloadLogs() {
      this.logPage = 1;
      await this.loadLogs();
    },
    async loadLogs() {
      this.logsLoading = true;
      try {
        const result = await newsApi.listRecords({ sourceId: this.logSourceId, page: this.logPage - 1, size: this.logPageSize });
        this.logs = Array.isArray(result?.items) ? result.items : [];
        this.logTotal = Number(result?.total || 0);
      } catch (error) { this.$emit('error', error); }
      finally { this.logsLoading = false; }
    },
    formatTime(value) {
      if (!value) return '-';
      const date = new Date(value);
      return Number.isNaN(date.getTime()) ? value : date.toLocaleString('zh-CN', { hour12: false });
    },
    recordStatusLabel(status) {
      return ({ NEW: '新增', QUEUED: '排队中', INDEXED: '已索引', DUPLICATE: '重复', FAILED: '失败' })[status] || status || '-';
    },
    recordStatusType(status) {
      return ({ INDEXED: 'success', FAILED: 'danger', DUPLICATE: 'info', QUEUED: 'warning', NEW: 'primary' })[status] || 'info';
    },
    analysisStatusLabel(status) {
      return ({ PENDING: '待分析', PROCESSING: '分析中', COMPLETED: '已完成', FAILED: '失败' })[status] || status || '-';
    },
    resetPage() { this.page = 1; },
    resetFilters() {
      this.filters = { keyword: '', sourceType: '', enabled: '' };
      this.page = 1;
    },
    sourceTypeLabel(type) {
      return this.sourceTypeOptions.find((option) => option.value === type)?.label || type || '-';
    },
    createSource() {
      this.form = emptyForm();
      this.selectedCollectionTemplateCode = '';
      this.structuredFlashConfigText = '';
      this.scheduleEditor = decodeCron(this.form.scheduleCron);
      this.dialogOpen = true;
    },
    async editSource(source) {
      try {
        const rule = await newsApi.getRule(source.id);
        this.form = { ...emptyForm(), ...source, configuration: { ...emptyForm().configuration, ...(source.configuration || {}) }, rule: { ...emptyRule(), ...(rule || {}) } };
        this.selectedCollectionTemplateCode = source.configuration?.templateCode || '';
        this.structuredFlashConfigText = source.sourceType === 'STRUCTURED_FLASH'
          ? JSON.stringify(this.form.configuration, null, 2) : '';
        this.scheduleEditor = decodeCron(this.form.scheduleCron);
        this.dialogOpen = true;
      } catch (error) { this.$emit('error', error); }
    },
    applyCollectionTemplate(code) {
      const template = this.collectionTemplates.find(item => item.code === code);
      if (!template) return;
      const defaults = emptyForm();
      this.form = {
        ...defaults,
        id: this.form.id,
        sourceCode: this.form.sourceCode,
        sourceName: this.form.sourceName,
        entryUrl: this.form.entryUrl,
        collectionDescription: this.form.collectionDescription || template.description || '',
        allowedDomain: this.form.allowedDomain,
        enabled: false,
        sourceType: template.sourceType,
        scheduleCron: template.scheduleCron || defaults.scheduleCron,
        configuration: { ...defaults.configuration, ...(template.configuration || {}) },
        rule: { ...emptyRule(), ...(template.rule || {}) }
      };
      this.structuredFlashConfigText = template.sourceType === 'STRUCTURED_FLASH'
        ? JSON.stringify(this.form.configuration, null, 2) : '';
      this.scheduleEditor = decodeCron(this.form.scheduleCron);
      this.$emit('notify', { title: '已应用采集模板', message: template.name });
    },
    fillAllowedDomainFromEntryUrl() {
      if (this.form.allowedDomain || !this.form.entryUrl) return;
      try {
        const host = new URL(this.form.entryUrl).hostname.toLowerCase();
        this.form.allowedDomain = host.startsWith('www.') ? host.slice(4) : host;
      } catch (error) {
        // URL validity is checked again when the source is saved.
      }
    },
    async save() {
      if (!this.validateScheduleWindow()) return;
      if (this.form.sourceType === 'STRUCTURED_FLASH') {
        try {
          const parsed = JSON.parse(this.structuredFlashConfigText || '{}');
          if (!parsed?.request?.url || !parsed?.response?.itemsPath || !parsed?.mapping?.sourceUrl) {
            this.$emit('notify', { type: 'danger', title: '结构化快讯配置不完整',
              message: '请填写 request.url、response.itemsPath 和 mapping.sourceUrl。' });
            return;
          }
          parsed.sleepMillis = this.form.configuration.sleepMillis;
          parsed.timeoutMillis = this.form.configuration.timeoutMillis;
          parsed.zoneId = this.form.configuration.zoneId;
          parsed.language = this.form.configuration.language;
          parsed.legalRisk = Boolean(this.form.configuration.legalRisk);
          parsed.compliance = { ...(parsed.compliance || {}), legalRisk: Boolean(this.form.configuration.legalRisk) };
          parsed.scheduleWindowEnabled = Boolean(this.form.configuration.scheduleWindowEnabled);
          parsed.scheduleWindowStart = this.form.configuration.scheduleWindowStart;
          parsed.scheduleWindowEnd = this.form.configuration.scheduleWindowEnd;
          this.form.configuration = parsed;
        } catch (error) {
          this.$emit('notify', { type: 'danger', title: '结构化快讯 JSON 格式错误', message: error.message });
          return;
        }
      }
      this.saving = true;
      try {
        this.applyVisualSchedule();
        const payload = { ...this.form, rule: undefined };
        const saved = await newsApi.saveSource(payload);
        if (['WEB_LIST', 'WEB_SINGLE_PAGE'].includes(saved.sourceType)) await newsApi.saveRule(saved.id, this.form.rule);
        this.dialogOpen = false;
        this.$emit('notify', { title: '资讯源配置已保存' });
        await this.load();
      } catch (error) { this.$emit('error', error); }
      finally { this.saving = false; }
    },
    async toggle(source) {
      try {
        if (!source.enabled) {
          const report = await this.runRobotsCheck(source, false);
          if (!report?.allowed) return;
        }
        await newsApi.saveSource({ ...source, enabled: !source.enabled });
        await this.load();
      }
      catch (error) { this.$emit('error', error); }
    },
    async runRobotsCheck(source, showSuccess = true) {
      this.checkingRobotsId = source.id;
      try {
        const report = await newsApi.checkRobots(source.id);
        if (!report?.allowed) {
          this.$emit('notify', { type: 'danger', title: '机器人协议检测未通过', message: report?.message || '无法确认该网站允许采集' });
          this.$emit('result', { title: `${source.sourceName} robots.txt 检测结果`, value: report });
        } else if (report?.overridden) {
          this.$emit('notify', { type: 'warning', title: '已使用临时忽略检测', message: report?.message || '当前采集由人工豁免放行' });
        } else if (showSuccess) {
          this.$emit('notify', { title: '机器人协议检测通过', message: report?.message || '允许访问该采集地址' });
        }
        return report;
      } finally { this.checkingRobotsId = null; }
    },
    async checkRobots(source) {
      try { await this.runRobotsCheck(source, true); }
      catch (error) { this.$emit('error', error); }
    },
    robotsOverrideActive(source) {
      const config = source?.configuration || {};
      const until = Date.parse(config.robotsPolicyOverrideUntil || '');
      return config.robotsPolicyOverride === true && Number.isFinite(until) && until > Date.now();
    },
    openRobotsOverride(source) {
      this.robotsOverrideSource = source;
      this.robotsOverrideForm = { reason: '', hours: 24, acknowledged: false };
      this.robotsOverrideDialogOpen = true;
    },
    async saveRobotsOverride() {
      const reason = String(this.robotsOverrideForm.reason || '').trim();
      if (reason.length < 10) {
        this.$emit('notify', { type: 'danger', title: '请补充忽略原因', message: '忽略原因至少填写 10 个字符，说明授权依据或临时处置背景。' });
        return;
      }
      if (!this.robotsOverrideForm.acknowledged) {
        this.$emit('notify', { type: 'danger', title: '请确认风险声明', message: '确认后才能创建临时忽略。' });
        return;
      }
      const source = this.robotsOverrideSource;
      const hours = Math.max(1, Math.min(168, Number(this.robotsOverrideForm.hours || 24)));
      const now = new Date();
      const until = new Date(now.getTime() + hours * 60 * 60 * 1000);
      this.robotsOverrideSaving = true;
      try {
        await newsApi.saveSource({ ...source, configuration: { ...(source.configuration || {}),
          robotsPolicyOverride: true, robotsPolicyOverrideReason: reason,
          robotsPolicyOverrideAt: now.toISOString(), robotsPolicyOverrideUntil: until.toISOString() } });
        this.robotsOverrideDialogOpen = false;
        this.$emit('notify', { type: 'warning', title: '已创建临时忽略', message: `有效期至 ${until.toLocaleString('zh-CN', { hour12: false })}` });
        await this.load();
      } catch (error) { this.$emit('error', error); }
      finally { this.robotsOverrideSaving = false; }
    },
    async cancelRobotsOverride(source) {
      try {
        await ElMessageBox.confirm('取消后，下次启用或采集将重新强制执行 robots.txt 检测。', '取消忽略检测', {
          confirmButtonText: '确认取消', cancelButtonText: '保留忽略', type: 'warning'
        });
        await newsApi.saveSource({ ...source, configuration: { ...(source.configuration || {}),
          robotsPolicyOverride: false, robotsPolicyOverrideReason: '', robotsPolicyOverrideUntil: '' } });
        this.$emit('notify', { title: '已取消忽略检测' });
        await this.load();
      } catch (error) {
        if (error !== 'cancel' && error !== 'close') this.$emit('error', error);
      }
    },
    async collect(source) {
      this.collectingId = source.id;
      try {
        const result = await newsApi.collect(source.id);
        if (result?.robotsAllowed === false) {
          this.$emit('notify', { type: 'danger', title: '机器人协议检测未通过', message: result.errorMessage || '采集已停止' });
        } else if (result?.robotsStatus === 'OVERRIDDEN') {
          this.$emit('notify', { type: 'warning', title: '本次采集使用了临时忽略', message: `有效期至 ${result.robotsOverrideUntil || '-'}` });
        }
        this.$emit('result', { title: `${source.sourceName} 采集结果`, value: result });
        await this.load();
      }
      catch (error) { this.$emit('error', error); }
      finally { this.collectingId = null; }
    },
    async remove(source) {
      try { await newsApi.removeSource(source.id); await this.load(); }
      catch (error) { this.$emit('error', error); }
    },
    applyVisualSchedule() {
      const editor = this.scheduleEditor;
      if (editor.mode === 'advanced') return;
      if (editor.mode === 'interval') {
        this.form.scheduleCron = editor.intervalCron;
        return;
      }
      const [hour, minute] = String(editor.time || '09:00').split(':');
      if (editor.mode === 'daily') {
        this.form.scheduleCron = `0 ${Number(minute)} ${Number(hour)} * * *`;
      } else if (editor.mode === 'weekly') {
        if (!editor.weekdays.length) editor.weekdays = ['MON'];
        const days = weekdayOptions.filter((option) => editor.weekdays.includes(option.value)).map((option) => option.value);
        this.form.scheduleCron = `0 ${Number(minute)} ${Number(hour)} * * ${days.join(',')}`;
      } else if (editor.mode === 'monthly') {
        if (!editor.monthDays.length) editor.monthDays = ['1'];
        const days = monthDayOptions.filter((option) => editor.monthDays.includes(option.value)).map((option) => option.value);
        this.form.scheduleCron = `0 ${Number(minute)} ${Number(hour)} ${days.join(',')} * *`;
      }
    },
    toggleMonthDay(day) {
      const selected = this.scheduleEditor.monthDays;
      this.scheduleEditor.monthDays = selected.includes(day) ? selected.filter((item) => item !== day) : [...selected, day];
      this.applyVisualSchedule();
    },
    describeCron(cron) {
      return decodeCron(cron).description;
    },
    describeScheduleWindow(configuration) {
      if (!configuration?.scheduleWindowEnabled) return '';
      return `采集时段 ${configuration.scheduleWindowStart || '--:--'}–${configuration.scheduleWindowEnd || '--:--'}`;
    },
    validateScheduleWindow() {
      const configuration = this.form.configuration || {};
      if (!configuration.scheduleWindowEnabled) return true;
      if (!configuration.scheduleWindowStart || !configuration.scheduleWindowEnd) {
        this.$emit('notify', { type: 'danger', title: '请完整设置采集时段', message: '启用时间段后，开始和结束时间都不能为空。' });
        return false;
      }
      if (configuration.scheduleWindowStart === configuration.scheduleWindowEnd) {
        this.$emit('notify', { type: 'danger', title: '采集时段无效', message: '开始时间和结束时间不能相同。' });
        return false;
      }
      return true;
    }
  }
};
